import { describe, expect, it } from 'vitest';
import {
  describeArtifact,
  prepareReviewPackage,
  type ReviewPackageV1,
} from '@lexaegis/protocol/v1';
import { artifactBytes, protocolCase } from '../registry/test-helpers';
import { verifyOffline, type OfflineInput } from './offline';
import { verifyReceipt } from './verify-receipt';
import { caseReference, hashOf, scriptedPolicy, scriptedRegistry } from './test-helpers';

/*
 * Adversarial interoperability cases. Expected values are the Chapter 2 literal vectors; nothing is
 * regenerated by the code under test. These run in Node and in real Chromium (pnpm sdk:browser).
 */

const NOW = () => new Date('2026-10-09T12:00:00.000Z');
const codes = (issues: readonly { code: string }[]) => issues.map((issue) => issue.code);

function full(
  id: 'generic' | 'legal' | 'legal-revised',
  extra: Partial<OfflineInput> = {},
): OfflineInput {
  const vector = protocolCase(id);
  return {
    mode: 'full-package',
    expectedReference: vector.expected.reference,
    referenceOrigin: 'independent',
    opening: vector.opening,
    artifacts: artifactBytes(vector),
    ...extra,
  };
}

describe('committed arrays are order-sensitive', () => {
  it('reordering manifest artifacts or scope changes the commitment', async () => {
    const vector = protocolCase('legal');
    const reordered = structuredClone(vector.opening);
    reordered.manifest.artifacts.reverse();
    expect((await verifyOffline(full('legal', { opening: reordered }))).ok).toBe(true);
    const result = await verifyOffline(full('legal', { opening: reordered }));
    expect(result.ok && result.data.manifestIntegrity).toBe('mismatch');
    const scope = structuredClone(vector.opening);
    scope.manifest.approval.scopeArtifactIds.reverse();
    const scoped = await verifyOffline(full('legal', { opening: scope }));
    expect(scoped.ok && scoped.data.manifestIntegrity).toBe('mismatch');
  });
});

describe('substitution', () => {
  it('a changed file with a rewritten, internally consistent manifest does not match the original reference', async () => {
    const vector = protocolCase('legal');
    const bytes = artifactBytes(vector);
    const source = vector.opening.manifest.artifacts.find((artifact) => artifact.role === 'source');
    if (source === undefined) throw new Error('no source');
    const altered = Uint8Array.from(bytes.get(source.id) ?? []);
    altered[0] = (altered[0] ?? 0) ^ 1;
    bytes.set(source.id, altered);
    // The attacker recomputes every digest and prepares a fresh, perfectly consistent package.
    const rewritten: ReviewPackageV1 = structuredClone(vector.opening.manifest);
    rewritten.artifacts = await Promise.all(
      rewritten.artifacts.map((artifact) =>
        describeArtifact(
          {
            id: artifact.id,
            role: artifact.role,
            mediaType: artifact.mediaType,
            label: artifact.label,
          },
          bytes.get(artifact.id) ?? new Uint8Array(),
        ),
      ),
    );
    const prepared = await prepareReviewPackage(rewritten, bytes);
    if (!prepared.ok) throw new Error(prepared.error.code);
    // Alone it verifies against its own reference ...
    const selfConsistent = await verifyOffline({
      mode: 'full-package',
      expectedReference: prepared.data.reference,
      referenceOrigin: 'file-declared',
      opening: prepared.data.opening,
      artifacts: prepared.data.artifacts(),
    });
    expect(selfConsistent.ok && selfConsistent.data.artifactIntegrity).toBe('match');
    // ... but the independently supplied original reference catches the substitution.
    const caught = await verifyOffline({
      mode: 'full-package',
      expectedReference: vector.expected.reference,
      referenceOrigin: 'independent',
      declaredReference: prepared.data.reference,
      opening: prepared.data.opening,
      artifacts: prepared.data.artifacts(),
    });
    expect(caught.ok && caught.data.manifestIntegrity).toBe('mismatch');
    expect(caught.ok && codes(caught.data.issues)).toEqual(
      expect.arrayContaining(['DECLARED_REFERENCE_CONFLICT']),
    );
    expect(caught.ok && caught.data.verifiedOpening).toBeNull();
  });
});

describe('modes never overclaim', () => {
  it('reference-only and manifest-only can never report artifact integrity as a match', async () => {
    for (const id of ['generic', 'legal', 'legal-revised'] as const) {
      const vector = protocolCase(id);
      const ref = await verifyOffline({
        mode: 'reference-only',
        expectedReference: vector.expected.reference,
        referenceOrigin: 'independent',
      });
      const manifest = await verifyOffline({
        mode: 'manifest-only',
        expectedReference: vector.expected.reference,
        referenceOrigin: 'independent',
        opening: vector.opening,
        // Even if files are handed in, a manifest-only check does not look at them.
        artifacts: artifactBytes(vector),
      });
      expect(ref.ok && [ref.data.manifestIntegrity, ref.data.artifactIntegrity]).toEqual([
        'unknown',
        'unknown',
      ]);
      expect(
        manifest.ok && [manifest.data.manifestIntegrity, manifest.data.artifactIntegrity],
      ).toEqual(['match', 'unknown']);
    }
  });

  it('an unknown application profile is generically verifiable and its semantics stay unevaluated', async () => {
    // The generic vector's profile id is not the legal profile and nothing here knows about it.
    const result = await verifyReceipt({ ...full('generic'), now: NOW });
    expect(result.ok && result.data.report).toMatchObject({
      artifactIntegrity: 'match',
      profile: { id: 'example.generic-review', version: '1' },
      profileSemantics: 'not_evaluated',
    });
  });
});

describe('registry failures are never successes', () => {
  const legal = caseReference('legal');
  const run = (registry: ReturnType<typeof scriptedRegistry>) =>
    verifyReceipt({
      ...full('legal'),
      live: { policy: scriptedPolicy(), transport: { kind: 'client', client: registry.client } },
      now: NOW,
    });

  it('a wrong protocol version is an identity mismatch', async () => {
    const result = await run(
      scriptedRegistry({ [legal.commitment]: { status: 1 } }, { protocolVersion: 2n }),
    );
    expect(result.ok && result.data.report).toMatchObject({
      registryIdentity: 'mismatch',
      chainStatus: 'unknown',
    });
    expect(result.ok && codes(result.data.report.issues)).toContain('LIVE_PROTOCOL_MISMATCH');
  });

  it('a block whose hash changes between reads is rejected, not accepted', async () => {
    const result = await run(
      scriptedRegistry({ [legal.commitment]: { status: 1 } }, { reorganise: true }),
    );
    expect(result.ok && result.data.report.chainStatus).toBe('unknown');
    expect(result.ok && codes(result.data.report.issues)).toContain('LIVE_BLOCK_CHANGED');
  });

  it('a node that refuses historical reads leaves the status unknown instead of falling back to latest', async () => {
    const registry = scriptedRegistry(
      { [legal.commitment]: { status: 1 } },
      { refuseHistorical: true },
    );
    const result = await run(registry);
    expect(result.ok && result.data.report.chainStatus).toBe('unknown');
    expect(result.ok && result.data.report.registryIdentity).toBe('unknown');
    expect(registry.calls).not.toContain('tag:latest');
    // The local result survives.
    expect(result.ok && result.data.report.artifactIntegrity).toBe('match');
  });

  it('an unknown status enum value is unknown, never active or not_found', async () => {
    const result = await run(
      scriptedRegistry({ [legal.commitment]: { status: 1 } }, { rawStatus: 9n }),
    );
    expect(result.ok && result.data.report.chainStatus).toBe('unknown');
    expect(result.ok && codes(result.data.report.issues)).toContain('LIVE_RESPONSE_INVALID');
  });

  it('a result for an older generation is distinguishable from the current one', async () => {
    const registry = scriptedRegistry({ [legal.commitment]: { status: 1 } });
    const [first, second] = await Promise.all([
      verifyReceipt({
        ...full('legal'),
        generation: 1,
        live: { policy: scriptedPolicy(), transport: { kind: 'client', client: registry.client } },
        now: NOW,
      }),
      verifyReceipt({ ...full('legal'), generation: 2, now: NOW }),
    ]);
    expect(first.ok && first.data.generation).toBe(1);
    expect(second.ok && second.data.generation).toBe(2);
    // A later offline-only generation never inherits a chain status from an earlier live one.
    expect(second.ok && second.data.report.chainStatus).toBe('unknown');
  });
});

describe('errors never echo artifact content', () => {
  it('reports opaque identifiers and codes only', async () => {
    const vector = protocolCase('legal');
    const bytes = artifactBytes(vector);
    const [firstId] = [...bytes.keys()];
    if (firstId === undefined) throw new Error('no artifact');
    bytes.set(firstId, new TextEncoder().encode('TOP-SECRET-BODY-TEXT'));
    const result = await verifyReceipt({ ...full('legal', { artifacts: bytes }), now: NOW });
    expect(JSON.stringify(result)).not.toContain('TOP-SECRET');
    expect(result.ok && codes(result.data.report.issues)).toContain('ARTIFACT_LENGTH_MISMATCH');
    expect(hashOf(1n)).toHaveLength(66);
  });
});
